int smb2_tcon(unsigned int xid, struct cifs_ses *ses, const char *tree, struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc;
    unsigned char *utf16_path = NULL;
    int utf16_path_len;
    struct smb2_tree_connect_request *req;
    struct smb2_tree_connect_response *resp;
    struct kvec iov[1];
    struct kvec rsp_iov;
    int rsp_iov_count;
    int bytes_read;

    if (!ses || !tcon || !tree)
        return -EINVAL;

    utf16_path_len = cifs_str_to_utf16((__le16 *)tree, strlen(tree), cp, NULL);
    if (utf16_path_len < 0) {
        cifs_dbg(VFS, "Unicode conversion of %s failed, error code %d\n", tree, utf16_path_len);
        return utf16_path_len;
    }

    utf16_path = kmalloc(utf16_path_len, GFP_KERNEL);
    if (!utf16_path)
        return -ENOMEM;

    utf16_path_len = cifs_str_to_utf16((__le16 *)utf16_path, strlen(tree), cp, NULL);
    if (utf16_path_len < 0) {
        kfree(utf16_path);
        return utf16_path_len;
    }

    req = kzalloc(sizeof(*req) + utf16_path_len, GFP_KERNEL);
    if (!req) {
        kfree(utf16_path);
        return -ENOMEM;
    }

    req->sync_hdr.MessageId = cpu_to_le64(xid);
    req->sync_hdr.SessionId = ses->ses_id;
    req->PathOffset = cpu_to_le16(offsetof(struct smb2_tree_connect_request, Buffer));
    req->PathLength = cpu_to_le16(utf16_path_len);
    memcpy(req->Buffer, utf16_path, utf16_path_len);

    iov[0].iov_base = req;
    iov[0].iov_len = sizeof(*req) + utf16_path_len;

    rc = cifs_call_async(ses, iov, 1, NULL, NULL, 0, NULL, NULL, NULL);
    if (rc) {
        kfree(utf16_path);
        kfree(req);
        return rc;
    }

    rc = cifs_setup_response(ses, &iov, 1, &rsp_iov, &rsp_iov_count, &bytes_read);
    if (rc) {
        kfree(utf16_path);
        kfree(req);
        return rc;
    }

    resp = (struct smb2_tree_connect_response *)rsp_iov.iov_base;

    tcon->share_type = le16_to_cpu(resp->ShareType);
    tcon->capabilities = le32_to_cpu(resp->Capabilities);
    memcpy(tcon->share_name, tree, strlen(tree));
    tcon->share_name[strlen(tree)] = '\0';

    kfree(utf16_path);
    kfree(req);
    cifs_free_bvec(&iov, 1);

    return 0;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc = 0;
    char *utf16_path = NULL;
    int utf16_path_len = 0;
    struct smb2_tree_connect_request *req = NULL;
    struct smb2_tree_connect_response *resp = NULL;
    struct TCP_Server_Info *server = ses->server;

    if (!ses || !tree || !tcon || !cp)
        return -EINVAL;

    utf16_path_len = cifsConvertToUTF16(NULL, tree, strlen(tree), 0, cp, NULL);
    if (utf16_path_len < 0) {
        rc = utf16_path_len;
        goto out;
    }

    utf16_path = kmalloc(utf16_path_len, GFP_KERNEL);
    if (!utf16_path) {
        rc = -ENOMEM;
        goto out;
    }

    rc = cifsConvertToUTF16(utf16_path, tree, strlen(tree), 0, cp, NULL);
    if (rc < 0)
        goto out;

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    resp = cifs_buf_get();
    if (!resp) {
        rc = -ENOMEM;
        goto out_free_req;
    }

    /* Initialize the tree connect request */
    memset(req, 0, sizeof(*req));
    req->StructureSize = sizeof(*req);
    req->PathOffset = offsetof(typeof(*req), Buffer);
    req->PathLength = utf16_path_len;
    memcpy(req->Buffer, utf16_path, utf16_path_len);

    rc = SMB2_ioctl(xid, ses, tcon, FSCTL_TREE_CONNECT, req, sizeof(*req),
                    (void **)&resp, CIFS_MAX_BUF_SIZE);
    if (rc)
        goto out_free_resp;

    /* Update tcon with response data */
    tcon->share_type = resp->ShareType;
    tcon->capabilities = resp->Capabilities;
    tcon->maximal_access = resp->MaximalAccess;

out_free_resp:
    cifs_buf_release(resp);
out_free_req:
    cifs_buf_release(req);
out:
    kfree(utf16_path);
    if (rc < 0)
        tcon->need_reconnect = true;
    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc;
    struct smb2_tree_connect_req *req;
    struct smb2_tree_connect_rsp *rsp;
    __le16 *utf16_path = NULL;
    char *unc_path = NULL;

    if (!ses || !tree || !tcon || !cp)
        return -EINVAL;

    unc_path = kmalloc(2 + strlen(tree) + 1, GFP_KERNEL);
    if (!unc_path) {
        rc = -ENOMEM;
        goto out;
    }

    snprintf(unc_path, 2 + strlen(tree) + 1, "\\\\%s", tree);

    utf16_path = cifs_strndup_to_utf16(unc_path, strlen(unc_path), cp, &rc);
    if (!utf16_path || rc) {
        kfree(unc_path);
        goto out;
    }

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    rsp = cifs_tree_connect_init(xid, ses, req, utf16_path, tcon->tid, tcon->ses->server);
    if (!rsp) {
        rc = -EFAULT;
        goto out_free;
    }

    rc = cifs_call_async(ses->server, req, rsp, NULL, NULL);
    if (rc)
        goto out_free;

    tcon->share_type = le32_to_cpu(rsp->ShareType);
    tcon->capabilities = le32_to_cpu(rsp->Capabilities);

out_free:
    cifs_buf_free(req);
    cifs_buf_free(rsp);
    kfree(utf16_path);
    kfree(unc_path);
out:
    return rc;
}

int cifs_tree_connect(const unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc = 0;
    wchar_t *utf16_tree = NULL;
    char *unc_path = NULL;

    if (!ses || !tree || !tcon || !cp) {
        return -EINVAL;
    }

    unc_path = kmalloc(PATH_MAX, GFP_KERNEL);
    if (!unc_path) {
        return -ENOMEM;
    }

    rc = cifs_build_unc_path(unc_path, tree, ses->prepath, cp);
    if (rc) {
        kfree(unc_path);
        return rc;
    }

    utf16_tree = utf8_utf16_alloc(tree, strlen(tree), cp);
    if (!utf16_tree) {
        kfree(unc_path);
        return -ENOMEM;
    }

    rc = SMB2_tree_connect(xid, ses, unc_path, utf16_tree, tcon);
    if (rc) {
        kfree(unc_path);
        kfree(utf16_tree);
        return rc;
    }

    tcon->tid = ses->tid;
    tcon->tid_str = kstrdup(tree, GFP_KERNEL);

    kfree(unc_path);
    kfree(utf16_tree);
    return 0;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc;
    char *utf16_path = NULL;
    char *full_path = NULL;
    struct smb2_tree_connect_req *req;
    struct smb2_tree_connect_rsp *rsp;

    if (!ses || !tree || !tcon || !cp) {
        rc = -EINVAL;
        goto out;
    }

    full_path = kmalloc(MAX_TREE_ID_LENGTH, GFP_KERNEL);
    if (!full_path) {
        rc = -ENOMEM;
        goto out;
    }

    snprintf(full_path, MAX_TREE_ID_LENGTH, "\\\\%s\\%s", ses->serverName, tree);

    utf16_path = kmalloc(MAX_TREE_ID_LENGTH * sizeof(__u16), GFP_KERNEL);
    if (!utf16_path) {
        rc = -ENOMEM;
        goto out;
    }

    rc = cifsConvertToUtf16(utf16_path, full_path,
                            MAX_TREE_ID_LENGTH, cp);
    if (rc < 0)
        goto out;

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    memset(req, 0, sizeof(*req));
    req->sync_hdr.MessageId = cpu_to_le64(xid);
    req->sync_hdr.SessionId = ses->ses_id;
    req->BufferFormat = SMB2_UNICODE;
    req->ByteCount = cpu_to_le16(MAX_TREE_ID_LENGTH * sizeof(__u16));
    memcpy(req->Path, utf16_path, req->ByteCount);

    rc = SMB2_ioctl(ses, tcon, SMB2_TREE_CONNECT, req, NULL, NULL, 0);
    if (rc < 0)
        goto out_free_req;

    rsp = (struct smb2_tree_connect_rsp *)((char *)req + rc);
    if (!rsp) {
        rc = -EIO;
        goto out_free_req;
    }

    tcon->share_type = rsp->ShareType;
    tcon->capabilities = rsp->Capabilities;

    out_free_req:
    cifs_buf_release(req);
    out:
    kfree(utf16_path);
    kfree(full_path);

    if (rc < 0) {
        tcon->flags |= TC_DISCONNECTED;
        ses->server->need_reconnect = true;
    }

    return rc;
}
